import java.util.Scanner;

public class CalculadoraPropinas {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        System.out.print("Bill total: ");
        String totalStr = sc.nextLine();
        double total = Double.parseDouble(totalStr);

        double propina15 = total * 0.15;
        double total15 = total + propina15;

        double propina20 = total * 0.20;
        double total20 = total + propina20;

        System.out.println("\n--- Tip options ---");
        System.out.printf("Original total: $%.2f%n", total);
        System.out.printf("15%%: +$%.2f = $%.2f%n", propina15, total15);
        System.out.printf("20%%: +$%.2f = $%.2f%n", propina20, total20);

        System.out.println("\n--- Truncated version (no decimals) ---");
        System.out.println("Original total: $" + (int) total);
        System.out.println("With 15%: $" + (int) total15);
        System.out.println("With 20%: $" + (int) total20);

        sc.close();
    }
}

